class ButtonLoader{static show(a){a&&(a.classList.contains("btn-loading")||(a.dataset.originalText=a.innerHTML,a.innerHTML=`
            <span class="btn-text">
                ${a.dataset.originalText}
            </span>

            <span class="btn-loader"></span>
        `,a.disabled=!0,a.classList.add("btn-loading")))}static hide(a){a&&(a.innerHTML=a.dataset.originalText,a.disabled=!1,a.classList.remove("btn-loading"))}}
